"""Explicit project annotations grounded in raw turns, never generated by relation()."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parent
raw=json.loads((ROOT/'data/project-conversations.json').read_text(encoding='utf-8'))
lookup={}
dates={}
for sample in raw:
    for key,turns in sample['conversation'].items():
        if not re.fullmatch(r'session_\d+',key):continue
        for t in turns:
            lookup[(sample['sample_id'],t['dia_id'])]=t
            dates[(sample['sample_id'],t['dia_id'])]=sample['conversation'][key+'_date_time']

# Labels are written from the quoted source semantics, without calling the system resolver.
specs=[
 ('conv-26','What is Caroline\'s adoption status at the end of the conversation?', ['passed the adoption agency interviews','interviews_passed'],['D19:1'], [('D2:8','D13:1','UPDATE'),('D13:1','D19:1','UPDATE')], 'Caroline','adoption_status',None,'Researching, applying, and passing interviews are successive stages of the same stated process.'),
 ('conv-26','As of 2023-06-01, what was Caroline researching?', ['adoption agencies','researching'],['D2:8'], [],'Caroline','adoption_status','2023-06-01T23:59:59','Later application and interviews must not replace the state at the explicit earlier date.'),
 ('conv-30','Which company did Gina lose her job at?', ['Door Dash','DoorDash'],['D1:3','D6:4'], [('D1:3','D6:4','RETAIN')],'Gina',None,None,'Both sources report the same loss of employment. A later repetition is not a new contradictory job state.'),
 ('conv-30','Did Jon discuss contemporary dance as his top pick and running his own studio?', ['contemporary','running my own studio'],['D1:8','D5:4'], [('D1:8','D5:4','RETAIN')],'Jon',None,None,'A dance preference and operating a studio can coexist. The system should not discard one as a newer scalar value.'),
 ('conv-41','What was the name of Maria\'s puppy?', ['Coco'],['D30:1'], [('D30:1','D31:2','RETAIN')],'Maria',None,None,'A named puppy report and a shelter-adoption report do not by themselves prove mutually exclusive ownership or a replacement.'),
 ('conv-41','What activities did Maria mention doing with her friends?', ['watch movies, hike, and have game nights','movies, hike, and game nights'],['D2:17'], [],'Maria',None,None,'The named activities are a compatible set, not successive replacements.'),
 ('conv-42','What pets did Nate discuss, including turtles and an adopted pet?', ['turtles','adopted'],['D2:14','D12:5'], [('D2:14','D12:5','RETAIN')],'Nate',None,None,'The new adoption explicitly mentions other pets. Existing turtles are not invalidated by another pet.'),
 ('conv-42','What did Joanna receive from a major company after finishing her screenplay?', ['a rejection letter','rejection letter'],['D14:1'], [('D14:1','D17:19','RETAIN')],None,None,None,'A rejection by one company remains a historical event even if a film is later described as published. The later report does not erase the rejection.'),
 ('conv-43','What was John\'s highest basketball score that he reported?', ['40 points','40'],['D3:1'], [],'John',None,None,'The explicit highest-score report is the evidence. Other hobbies are not basketball score updates.'),
 ('conv-43','What sporting activities did John discuss, including his points and surfing?', ['40 points','surfing'],['D3:1','D3:27'], [('D3:1','D3:27','RETAIN')],'John',None,None,'Scoring in basketball and surfing are separate compatible activities, not mutually exclusive scalar values.'),
 ('conv-44','What is Andrew\'s pet ownership status at the end of the conversation?', ['owns_dog','two dogs','Having two dogs'],['D12:1','D24:2','D27:5'], [('D1:12','D12:1','SUPERSEDE'),('D12:1','D24:2','RETAIN')],'Andrew','pet_ownership',None,'The later explicit puppy ownership supersedes the earlier no-pets state. Further dog ownership is compatible, while the pet count needs a separate attribute.'),
 ('conv-44','As of 2023-03-28, did Andrew have any pets?', ['none','No, no pets right now','no pets'],['D1:12'], [],'Andrew','pet_ownership','2023-03-28T23:59:59','The no-pets statement precedes the later adoption. Future ownership is excluded for this explicit date.'),
]
questions,gold,audit=[],[],[]
for i,(cid,q,answers,evidence,pairs,entity,attribute,asof,rationale) in enumerate(specs,1):
    qid=f'project-dynamic-{i:02d}'
    request={'question_id':qid,'conversation_id':cid,'question':q}
    if entity:request['entity']=entity
    if attribute:request['attribute']=attribute
    if asof:request['as_of']=asof
    questions.append(request)
    gold.append({'question_id':qid,'answers':answers,'evidence':evidence,
                 'relations':[{'from_turn':a,'to_turn':b,'label':label} for a,b,label in pairs],
                 'provenance':'project AI-assisted annotation, not course gold',
                 'answer_convention':'listed spans are alternative acceptable evidence-bearing short answers; multi-part completeness is not measured'})
    source_ids=sorted(set(evidence+[t for a,b,_ in pairs for t in [a,b]]))
    audit.append({'question_id':qid,'rationale':rationale,'independent_human_review':False,
                  'sources':[{'turn':tid,'speaker':lookup[(cid,tid)]['speaker'],'text':lookup[(cid,tid)]['text'],'session_time':dates[(cid,tid)]} for tid in source_ids]})
for name,data in [('questions.dynamic.jsonl',questions),('gold.dynamic.jsonl',gold)]:
    (ROOT/'data/eval'/name).write_text('\n'.join(json.dumps(r,ensure_ascii=False) for r in data)+'\n',encoding='utf-8')
(ROOT/'data/eval/dynamic-annotation-audit.json').write_text(json.dumps({'kind':'self-built-diagnostic','not_course_gold':True,'single_ai_annotator':True,'cases':audit},ensure_ascii=False,indent=2),encoding='utf-8')
print('Prepared 12 grounded diagnostic cases; not official course annotations.')
